            decode_m(gm, OH, OW, n, oh, ow);
            const int ih = oh * sh - ph + kh * dh;
            const int iw = ow * sw - pw + kw * dw;
            if (ih >= 0 && ih < H) {
                src = input + ((n * C + c) * H + ih) * W + iw;
                vec_ok = (sw == 1) && (ow + 3 < OW) && (gm + 3 < M) &&
                         (iw >= 0) && (iw + 3 < W) &&
                         ((reinterpret_cast<unsigned long long>(src) & 15ull) == 0ull);
            }
        }
        if (vec_ok) {
            cp_async16(dst, src);
        } else {
            #pragma unroll
            for (int v = 0; v < 4; ++v) {
                const int gm_s = gm + v;
                const float* src_s = input;
                bool valid_s = false;
                if (gk < K && gm_s < M) {
                    int c, kh, kw, n, oh, ow;
                    decode_k(gk, KH, KW, c, kh, kw);
                    decode_m(gm_s, OH, OW, n, oh, ow);
                    const int ih = oh * sh - ph + kh * dh;
                    const int iw = ow * sw - pw + kw * dw;
                    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                        src_s = input + ((n * C + c) * H + ih) * W + iw;
                        valid_s = true;
                    }
                }
                cp_async4(dst + v, src_s, valid_s);
            }
        }
    }
    for (int idx = tid; idx < BK * BN; idx += BLOCK_THREADS) {
        const int oc_local = idx / BK;
        const int k_local = idx - oc_local * BK;
        const int gk = k0 + k_local;
        const int oc = n0 + oc_local;
        const float* src = weight;
        bool valid = false;
        if (gk < K && oc < OC) {
            src = weight + (long long)oc * K + gk;
            valid = true;
        }
        cp_async4(Bs_d + k_local * LDB + oc_local, src, valid);
    }
}
__global__ void conv2d_implicit_gemm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int OC, int KH, int KW,
    int OH, int OW,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int M, int K)
{
    extern __shared__ __align__(16) float smem[];
    float* As = smem;
    float* Bs = smem + STAGES * A_TILE;
    const int tid = threadIdx.x;
    const int m0 = blockIdx.x * BM;
    const int n0 = blockIdx.y * BN;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const int warp_id = tid >> 5;
    const int warp_m = (warp_id >> 1) * 32;
    const int warp_n = (warp_id & 1) * 32;
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[2][2];
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
            wmma::fill_fragment(acc[i][j], 0.0f);
        }
    }
#else
    const int tx = tid % (BN / TN);
    const int ty = tid / (BN / TN);
    const int m_base = ty * TM;
    const int n_base = tx * TN;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
#endif
    const int num_ktiles = (K + BK - 1) / BK;
    #pragma unroll
    for (int t = 0; t < STAGES - 1; ++t) {
        if (t < num_ktiles) {
            load_stage(input, weight, As, Bs, t, t * BK,
                       N, C, H, W, OC, KH, KW, OH, OW,
                       sh, sw, ph, pw, dh, dw, M, K, m0, n0, tid);
        }
        cp_async_commit();
    }
    for (int i = 0; i < num_ktiles; ++i) {
        cp_async_wait<STAGES - 2>();
        __syncthreads();
        const int read_stage = i % STAGES;
        const int next_tile = i + STAGES - 1;
        if (next_tile < num_ktiles) {
            load_stage(input, weight, As, Bs, next_tile % STAGES, next_tile * BK,
                       N, C, H, W, OC, KH, KW, OH, OW,
                       sh, sw, ph, pw, dh, dw, M, K, m0, n0, tid);
        }
        cp_async_commit();
        const float* As_r = As + read_stage * A_TILE;
        const float* Bs_r = Bs + read_stage * B_TILE;
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
        #pragma unroll
        for (int kk = 0; kk < BK; kk += 8) {
            wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> a_frag[2];
            wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> b_frag[2];
            #pragma unroll
            for (int fi = 0; fi < 2; ++fi) {
                wmma::load_matrix_sync(a_frag[fi], &As_r[kk * LDA + warp_m + fi * 16], LDA);
            }
            #pragma unroll
            for (int fj = 0; fj < 2; ++fj) {
                wmma::load_matrix_sync(b_frag[fj], &Bs_r[kk * LDB + warp_n + fj * 16], LDB);
            }
            #pragma unroll
            for (int fi = 0; fi < 2; ++fi) {
                #pragma unroll
                for (int fj = 0; fj < 2; ++fj) {
                    wmma::mma_sync(acc[fi][fj], a_frag[fi], b_frag[fj], acc[fi][fj]);
                }
            }
        }
#else
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            const float4 a_vec0 = *reinterpret_cast<const float4*>(&As_r[kk * LDA + m_base]);
            const float4 a_vec1 = *reinterpret_cast<const float4*>(&As_r[kk * LDA + m_base + 4]);
            const float4 b_vec = *reinterpret_cast<const float4*>(&Bs_r[kk * LDB + n_base]);
            const float a_frag[TM] = {a_vec0.x, a_vec0.y, a_vec0.z, a_vec0.w,
                                      a_vec1.x, a_vec1.y, a_vec1.z, a_vec1.w};
            const float b_frag[TN] = {b_vec.x, b_vec.y, b_vec.z, b_vec.w};
            #pragma unroll
            for (int ii = 0; ii < TM; ++ii) {
                #pragma unroll
                for (int jj = 0; jj < TN; ++jj) {
                    acc[ii][jj] += a_frag[ii] * b_frag[jj];
                }
            }
        }
#endif
    }
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    cp_async_wait<0>();
    __syncthreads();
    float* Cs = smem;
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
            wmma::store_matrix_sync(&Cs[(warp_n + j * 16) * BM + warp_m + i * 16],
                                    acc[i][j], BM, wmma::mem_col_major);
        }
    }
    __syncthreads();
    for (int idx = tid; idx < BM * BN; idx += BLOCK_THREADS) {
        const int nn = idx / BM;
        const int mm = idx - nn * BM;
        const int gm = m0 + mm;
        const int oc = n0 + nn;
        if (gm < M && oc < OC) {
            int n, oh, ow;
            decode_m(gm, OH, OW, n, oh, ow);
            float v = Cs[idx];
            if (bias != nullptr) v += bias[oc];
            output[((n * OC + oc) * OH + oh) * OW + ow] = v;
        }
    }
#else
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int gm = m0 + m_base + i;
        if (gm >= M) continue;
        int n, oh, ow;
        decode_m(gm, OH, OW, n, oh, ow);
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int oc = n0 + n_base + j;
            if (oc < OC) {
                float v = acc[i][j];
                if (bias != nullptr) v += bias[oc];
                output[((n * OC + oc) * OH + oh) * OW + ow] = v;
            }
        }
    }
#endif
}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    const int N = (int)input.size(0);
    const int C = (int)input.size(1);
    const int H = (int)input.size(2);
    const int W = (int)input.size(3);
    const int OC = (int)weight.size(0);
    const int KH = (int)weight.size(2);
    const int KW = (int)weight.size(3);
    TORCH_CHECK(weight.size(1) == C, "weight in_channels mismatch");
    const int sh = (int)stride_h;
    const int sw = (int)stride_w;
    const int ph = (int)pad_h;
    const int pw = (int)pad_w;
    const int dh = (int)dil_h;
    const int dw = (int)dil_w;
    const int eff_kh = (KH - 1) * dh + 1;
    const int eff_kw = (KW - 1) * dw + 1;
    const int OH = (H + 2 * ph - eff_kh) / sh + 1;
    const int OW = (W + 2 * pw - eff_kw) / sw + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto output = torch::empty({N, OC, OH, OW}, input.options());
    TORCH_CHECK(input.numel() < INT32_MAX && output.numel() < INT32_MAX, "tensor too large");
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->numel() == OC, "bias size mismatch");
        bias_ptr = bias->data_ptr<float>();
    }
    const int M = N * OH * OW;
    const int K = C * KH * KW;
    TORCH_CHECK(M > 0 && K > 0, "invalid reduction size");
    dim3 block(BLOCK_THREADS);
    dim3 grid((M + BM - 1) / BM, (OC + BN - 1) / BN);
    constexpr int SMEM_BYTES = STAGES * (A_TILE + B_TILE) * (int)sizeof(float);
    static bool smem_configured = false;
    if (!smem_configured) {
        C10_CUDA_CHECK(cudaFuncSetAttribute(
            (const void*)conv2d_implicit_gemm_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            SMEM_BYTES));
        smem_configured = true;
    }
    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_implicit_gemm_kernel<<<grid, block, SMEM_BYTES, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        OC, KH, KW,
        OH, OW,
        sh, sw, ph, pw, dh, dw,
        M, K);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
