    __syncthreads();
    for (int idx = tid; idx < BM * BN; idx += BLOCK_THREADS) {
        const int nn = idx / BM;
        const int mm = idx - nn * BM;
        const int gm = m0 + mm;
        const int oc = n0 + nn;
        if (gm < M && oc < OC) {
            int n, oh, ow;
            decode_m(gm, OH, OW, n, oh, ow);
            float v = Cs[idx];
            if (bias != nullptr) v += bias[oc];
            output[((n * OC + oc) * OH + oh) * OW + ow] = v;
        }
    }
#else
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int gm = m0 + m_base + i;
        if (gm >= M) continue;
        int n, oh, ow;
        decode_m(gm, OH, OW, n, oh, ow);
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int oc = n0 + n_base + j;
            if (oc < OC) {
                float v = acc[i][j];
                if (bias != nullptr) v += bias[oc];
                output[((n * OC + oc) * OH + oh) * OW + ow] = v;
