}
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    const int N = (int)input.size(0);
    const int C = (int)input.size(1);
    const int H = (int)input.size(2);
    const int W = (int)input.size(3);
    const int OC = (int)weight.size(0);
    const int KH = (int)weight.size(2);
    const int KW = (int)weight.size(3);
    TORCH_CHECK(weight.size(1) == C, "weight in_channels mismatch");
    const int sh = (int)stride_h;
    const int sw = (int)stride_w;
    const int ph = (int)pad_h;
    const int pw = (int)pad_w;
    const int dh = (int)dil_h;
    const int dw = (int)dil_w;
    const int eff_kh = (KH - 1) * dh + 1;
    const int eff_kw = (KW - 1) * dw + 1;
    const int OH = (H + 2 * ph - eff_kh) / sh + 1;
    const int OW = (W + 2 * pw - eff_kw) / sw + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto output = torch::empty({N, OC, OH, OW}, input.options());
    TORCH_CHECK(input.numel() < INT32_MAX && output.numel() < INT32_MAX, "tensor too large");
    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->numel() == OC, "bias size mismatch");
        bias_ptr = bias->data_ptr<float>();
    }
    const int M = N * OH * OW;
    const int K = C * KH * KW;
    TORCH_CHECK(M > 0 && K > 0, "invalid reduction size");
    dim3 block(BLOCK_THREADS);
    dim3 grid((M + BM - 1) / BM, (OC + BN - 1) / BN);
    constexpr int SMEM_BYTES = STAGES * (A_TILE + B_TILE) * (int)sizeof(float);
    static bool smem_configured = false;
    if (!smem_configured) {
        C10_CUDA_CHECK(cudaFuncSetAttribute(
            (const void*)conv2d_implicit_gemm_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            SMEM_BYTES));
        smem_configured = true;
    }
    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_implicit_gemm_kernel<<<grid, block, SMEM_BYTES, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        OC, KH, KW,
        OH, OW,
        sh, sw, ph, pw, dh, dw,
        M, K);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
