using namespace nvcuda;
constexpr int BM = 128;
constexpr int BN = 64;
constexpr int BK = 16;  // halve K-tile: dynamic smem/block drops ~51KB -> ~25.5KB (2 stages x (A 8.5KB + B 4.25KB)) so 2 CTAs finally fit in the 100KB SM smem budget; profiler showed occupancy still 16.7% and shared-memory limited because 2x51KB=102KB overflowed it, so this doubles theoretical occupancy to 33.3% while keeping TF32 WMMA (now 2 k8 steps per stage) and double-buffered cp.async
constexpr int BLOCK_THREADS = 256;
constexpr int TM = 8;
constexpr int TN = 4;
constexpr int STAGES = 2;  // keep double-buffered cp.async pipeline; combined with BK=16 the per-block footprint is 25.5KB, so the earlier 2x51KB=102KB overflow of the 100KB SM budget is resolved and 2 CTAs/SM now actually fit (registers at ~106/thread also cap residency at 2 CTAs, so this is the balanced point)
constexpr int LDA = BM + 8;  // pad A smem leading dim: WMMA col-major column stride 512B -> 544B rotates bank phases, cutting ~8-way load bank conflicts to ~2-way while keeping 16B cp.async/WMMA alignment
constexpr int LDB = BN + 4;  // pad B smem leading dim: row stride 256B -> 272B breaks 8-way row-major WMMA load bank conflicts
constexpr int A_TILE = BK * LDA;
constexpr int B_TILE = BK * LDB;
__device__ __forceinline__ void decode_k(
    int k, int KH, int KW, int& c, int& kh, int& kw)
{
    const int khw = KH * KW;
    c = k / khw;
    const int rem = k - c * khw;
    kh = rem / KW;
    kw = rem - kh * KW;
}
__device__ __forceinline__ void decode_m(
    int m, int OH, int OW, int& n, int& oh, int& ow)
{
    const int hw = OH * OW;
    n = m / hw;
    const int rem = m - n * hw;
    oh = rem / OW;
    ow = rem - oh * OW;
}
__device__ __forceinline__ void cp_async4(float* smem_dst, const float* gmem_src, bool valid)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
    const int src_size = valid ? 4 : 0;
    asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
                 :: "r"(dst), "l"(gmem_src), "r"(src_size));
#else
    *smem_dst = valid ? *gmem_src : 0.0f;
#endif
}
__device__ __forceinline__ void cp_async16(float* smem_dst, const float* gmem_src)
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
                 :: "r"(dst), "l"(gmem_src));
#else
    *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<const float4*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_commit()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int PENDING>
__device__ __forceinline__ void cp_async_wait()
{
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
